# Word frequency cut-off vs finished
import re
def words(t): return re.findall(r'[A-Za-z]+', t)
cut_words = Counter(); fin_words = Counter(); cut_tok=0; fin_tok=0
for r in rows:
    w = words(r['text'])
    if r['finish']=='length':
        cut_words.update(w); cut_tok += r['tokens']
    else:
        fin_words.update(w); fin_tok += r['tokens']
for w in ['Wait','wait','Hmm','Alternatively','Also','But','Actually','Let','checking','check']:
    print(w, 'cut/1ktok', 1000*cut_words[w]/cut_tok, 'fin/1ktok', 1000*fin_words[w]/fin_tok)

